const MAG_MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
const magNummer = (j, m) => Math.max(1, (j - MAG_START.jahr) * 12 + (m - MAG_START.monat) + 1);
